async function loadLogs(reset){if(LG.busy)return;if(ROLE!=="admin"){LG.err="Somente administradores podem ver os logs.";render();return}
LG.busy=true;LG.err="";if(reset){LG.rows=[];LG.more=false}render();
var q=DB.from("logs").select("id,criado_em,usuario_email,acao,entidade,descricao").order("id",{ascending:false}).limit(LGPAGE);
if(LG.acao)q=q.eq("acao",LG.acao);
if(LG.de)q=q.gte("criado_em",new Date(LG.de+"T00:00:00").toISOString());
if(LG.ate)q=q.lt("criado_em",new Date(new Date(LG.ate+"T00:00:00").getTime()+864e5).toISOString());
if(!reset&&LG.rows.length)q=q.lt("id",LG.rows[LG.rows.length-1].id);
var r;try{r=await q}catch(x){r={error:{message:"sem conexão"}}}LG.busy=false;LG.loaded=true;
if(r.error){LG.err="Não foi possível carregar os logs: "+r.error.message;render();return}
LG.rows=LG.rows.concat(r.data||[]);LG.more=(r.data||[]).length===LGPAGE;render()}
function lgDt(iso){var d=new Date(iso);return p2(d.getDate())+"/"+p2(d.getMonth()+1)+"/"+d.getFullYear()+" "+p2(d.getHours())+":"+p2(d.getMinutes())}
